	// c; the cursor rests on c.
	if r := got.Results[4]; !r.OK || r.InstanceID != "c" || r.Address != "h3:3" || r.Sequence != 1 || r.Revision != 1 {
		t.Fatalf("item 5 should choose c, got %+v", r)
