98		// 4: the padded key's first success rotates to the smallest healthy id (i3
99		// is unhealthy and i4 unknown, so neither is eligible) and binds s -> i1.
100		if r := got.Results[4]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:1" || r.Sequence != 11 || r.Revision != 1 {
