109			t.Fatalf("result 6 session reuse: %+v", r)
110		}
111	
112		// 7: resubmitting the complete list in another order with padding on every
113		// field trims back to the identical content: success with no "changed" and
114		// no revision bump — not a recreation of the service.
115		if r := got.Results[7]; !r.OK || r.Changed || r.Revision != 1 {
116			t.Fatalf("result 7 identical resubmission must be unchanged: %+v", r)
117		}
118		if strings.Contains(string(mustResultJSON(t, out, 7)), `"changed"`) {
119			t.Fatalf("result 7 JSON must not contain a changed field: %s", mustResultJSON(t, out, 7))
120		}
121	
122		// 8: the padded key trims to the SAME session: its binding survived the
123		// resubmission and returns i1's current address and accepted sequence.
124		if r := got.Results[8]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:1" || r.Sequence != 11 || r.Revision != 1 {
125			t.Fatalf("result 8 session survives resubmission: %+v", r)
126		}
127		// 9: the reuse did not move the cursor off i2; unhealthy i3 and unknown i4
128		// are not candidates, so the plain rotation wraps past the end to i1.
129		if r := got.Results[9]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:1" || r.Sequence != 11 || r.Revision != 1 {
130			t.Fatalf("result 9 plain select wraps to i1 regardless of resubmission order: %+v", r)
131		}
