15	func TestRegistryCreateAndUpdate(t *testing.T) {
16		r := NewRegistry()
17	
18		reg, err := r.ValidateRegistration("svc", 0, validInstances())
19		if err != nil {
20			t.Fatalf("validate: %v", err)
21		}
22		out := r.Apply(reg)
23		if !out.OK || !out.Changed || out.Revision != 1 {
24			t.Fatalf("create: got %+v", out)
25		}
26	
27		// Same content in different order: success, no revision bump.
28		reg, err = r.ValidateRegistration("svc", 1, []Instance{
29			{ID: "i1", Address: "10.0.0.1:443"},
30			{ID: "i2", Address: "h2.example:8080"},
31		})
32		if err != nil {
33			t.Fatalf("validate unchanged: %v", err)
34		}
35		out = r.Apply(reg)
36		if !out.OK || out.Changed || out.Revision != 1 {
37			t.Fatalf("unchanged: got %+v", out)
38		}
39	
40		// Content change bumps revision and fully replaces the list.
41		reg, err = r.ValidateRegistration("svc", 1, []Instance{
42			{ID: "i1", Address: "10.0.0.2:443"},
43			{ID: "i3", Address: "[2001:db8::1]:9090"},
44		})
45		if err != nil {
46			t.Fatalf("validate changed: %v", err)
47		}
48		out = r.Apply(reg)
49		if !out.OK || !out.Changed || out.Revision != 2 {
50			t.Fatalf("changed: got %+v", out)
51		}
52	
53		views := r.Snapshot()
54		if len(views) != 1 {
55			t.Fatalf("services: %+v", views)
56		}
57		got := views[0]
58		if got.Service != "svc" || got.Revision != 2 {
59			t.Fatalf("service: %+v", got)
60		}
61		want := []InstanceView{
62			{ID: "i1", Address: "10.0.0.2:443", Health: HealthUnknown},
63			{ID: "i3", Address: "[2001:db8::1]:9090", Health: HealthUnknown},
64		}
65		if len(got.Instances) != len(want) {
66			t.Fatalf("instances: %+v", got.Instances)
67		}
68		for i := range want {
69			if got.Instances[i] != want[i] {
70				t.Fatalf("instance %d: got %+v want %+v", i, got.Instances[i], want[i])
71			}
72		}
73	}
