141			{"port too high", "svc", 0, []Instance{{ID: "a", Address: "host:65536"}}},
142			{"port with sign", "svc", 0, []Instance{{ID: "a", Address: "host:+80"}}},
143			{"port with spaces", "svc", 0, []Instance{{ID: "a", Address: "host: 80"}}},
144			{"unbracketed ipv6", "svc", 0, []Instance{{ID: "a", Address: "::1:8080"}}},
145			{"bad bracketed ipv6", "svc", 0, []Instance{{ID: "a", Address: "[zzzz]:8080"}}},
146			{"bracketed without port", "svc", 0, []Instance{{ID: "a", Address: "[::1]"}}},
147			{"bad domain char", "svc", 0, []Instance{{ID: "a", Address: "my_host:80"}}},
148		}
149		for _, tc := range cases {
