92			{"service":"a","expectedRevision":1,"instances":[{"id":"y","address":"h:2"}]},
93			{"service":"a","expectedRevision":2,"instances":[{"id":"","address":"h:1"}]},
94			{"service":"a","expectedRevision":2,"instances":[{"id":"z","address":"nope"}]},
95			{"service":"b","expectedRevision":1,"instances":[]}
96		]}`
97		out, code := runRegisterWith(t, input)
98		if code != 1 {
99			t.Fatalf("exit code: %d", code)
100		}
101		var got registerOutput
102		if err := json.Unmarshal([]byte(out), &got); err != nil {
103			t.Fatalf("output is not JSON: %v\n%s", err, out)
104		}
105		if len(got.Results) != 6 {
106			t.Fatalf("results: %+v", got.Results)
107		}
108		// 0: create
109		if r := got.Results[0]; !r.OK || !r.Changed || r.Revision != 1 {
110			t.Fatalf("result 0: %+v", r)
111		}
112		// 1: conflict, expected 5 actual 1
113		if r := got.Results[1]; r.OK || r.Error != "conflict" || r.ExpectedRevision != 5 || r.ActualRevision != 1 || r.Revision != 1 {
114			t.Fatalf("result 1: %+v", r)
115		}
116		// 2: update to rev 2
117		if r := got.Results[2]; !r.OK || !r.Changed || r.Revision != 2 {
118			t.Fatalf("result 2: %+v", r)
119		}
120		// 3: invalid content with a matching revision: still invalid, list untouched
121		if r := got.Results[3]; r.OK || r.Error != "invalid" || r.Revision != 2 {
122			t.Fatalf("result 3: %+v", r)
123		}
124		// 4: invalid address
125		if r := got.Results[4]; r.OK || r.Error != "invalid" || r.Revision != 2 {
126			t.Fatalf("result 4: %+v", r)
127		}
128		// 5: conflict on a brand-new service
129		if r := got.Results[5]; r.OK || r.Error != "conflict" || r.ExpectedRevision != 1 || r.ActualRevision != 0 || r.Revision != 0 {
130			t.Fatalf("result 5: %+v", r)
131		}
132		// Only the successful registrations are reflected.
133		if len(got.Services) != 1 || got.Services[0].Service != "a" || got.Services[0].Revision != 2 {
134			t.Fatalf("services: %+v", got.Services)
135		}
136		if len(got.Services[0].Instances) != 1 || got.Services[0].Instances[0].ID != "y" {
137			t.Fatalf("instances: %+v", got.Services[0].Instances)
138		}
139	}
