767	func TestRejectedHealthKeepsHealthyInstanceEligible(t *testing.T) {
768		// A healthy instance that receives a stale or same-sequence conflicting
769		// "unhealthy" report keeps its accepted observation: the rejections state
770		// the reason and the accepted sequence, and the instance stays in the
771		// candidate set. The rejected reports target b, the instance the rotation
772		// would choose next; the cursor must neither skip it nor restart.
773		input := `{"requests":[
774			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"a","address":"h1:1"},{"id":"b","address":"h2:2"}]},
775			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":5,"healthy":true},
776			{"type":"health","service":"svc","instanceId":"b","expectedRevision":1,"sequence":7,"healthy":true},
777			{"type":"select","service":"svc","expectedRevision":1},
778			{"type":"health","service":"svc","instanceId":"b","expectedRevision":1,"sequence":3,"healthy":false,"reason":"flapping"},
779			{"type":"health","service":"svc","instanceId":"b","expectedRevision":1,"sequence":7,"healthy":false,"reason":"flapping"},
780			{"type":"select","service":"svc","expectedRevision":1},
781			{"type":"select","service":"svc","expectedRevision":1}
782		]}`
783		out, code := runRegisterWith(t, input)
784		if code != 1 {
785			t.Fatalf("exit code: %d, output: %s", code, out)
786		}
787		var got registerOutput
788		if err := json.Unmarshal([]byte(out), &got); err != nil {
789			t.Fatalf("output is not JSON: %v\n%s", err, out)
790		}
791		// One result per request, in input order.
792		if len(got.Results) != 8 {
793			t.Fatalf("results: %+v", got.Results)
794		}
795		// First select takes the smallest healthy id.
796		if r := got.Results[3]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 5 || r.Revision != 1 {
797			t.Fatalf("first select: %+v", r)
798		}
799		// Stale: sequence below the accepted 7. The failure states the reason and
800		// the currently accepted sequence, and keeps the service revision.
801		if r := got.Results[4]; r.OK || r.Error != "stale" ||
802			r.Reason != "sequence 3 is older than the current sequence 7" ||
803			r.Sequence != 7 || r.Revision != 1 {
804			t.Fatalf("stale report: %+v", r)
805		}
806		// Conflict: the accepted sequence 7 reused with the opposite health state.
807		if r := got.Results[5]; r.OK || r.Error != "conflict" ||
808			r.Reason != "sequence 7 already used with different health content" ||
809			r.Sequence != 7 || r.Revision != 1 {
810			t.Fatalf("conflicting report: %+v", r)
811		}
812		// The rejected "unhealthy" reports did not knock b out: the rotation
813		// continues just after a and lands on b with its accepted record.
814		if r := got.Results[6]; !r.OK || r.InstanceID != "b" || r.Address != "h2:2" || r.Sequence != 7 || r.Revision != 1 {
815			t.Fatalf("select after rejections should still choose b: %+v", r)
816		}
817		// Past the end the rotation wraps to the smallest id.
818		if r := got.Results[7]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 5 {
819			t.Fatalf("select should wrap to a: %+v", r)
820		}
821		// The final list shows only the accepted observations; nothing from the
822		// rejected reports leaked in.
823		if len(got.Services) != 1 || got.Services[0].Revision != 1 {
824			t.Fatalf("services: %+v", got.Services)
825		}
826		insts := got.Services[0].Instances
827		if len(insts) != 2 {
828			t.Fatalf("instances: %+v", insts)
829		}
830		if insts[0].ID != "a" || insts[0].Health != "healthy" || insts[0].Sequence != 5 || insts[0].Reason != "" {
831			t.Fatalf("a should keep its accepted record: %+v", insts[0])
832		}
833		if insts[1].ID != "b" || insts[1].Health != "healthy" || insts[1].Sequence != 7 || insts[1].Reason != "" {
834			t.Fatalf("b should keep its accepted record: %+v", insts[1])
835		}
836	}
