		{ID: "c", Address: "h3:3", Health: HealthHealthy, Sequence: 13},
		{ID: "d", Address: "h4:4", Health: HealthHealthy, Sequence: 14},
	}
	if len(views[0].Instances) != len(want) {
		t.Fatalf("instances: %+v", views[0].Instances)
	}
